import { useEffect, useState } from 'react'
import entries from './index.json'

// Index of every imported page and post (generated by `npm run import`).
export { entries }
export const bySlug = Object.fromEntries(entries.map((e) => [e.slug, e]))
export const posts = entries.filter((e) => e.type === 'post').sort((a, b) => b.date.localeCompare(a.date))
export const byGroup = (group) => entries.filter((e) => e.group === group)

/** Loads the full content of one page or post from /content/<slug>.json. */
export function useContent(slug) {
  const [state, setState] = useState({ slug: null, doc: null, error: false })

  useEffect(() => {
    let cancelled = false
    fetch(`/content/${slug}.json`)
      .then((res) => (res.ok ? res.json() : Promise.reject(new Error(res.statusText))))
      .then((doc) => !cancelled && setState({ slug, doc, error: false }))
      .catch(() => !cancelled && setState({ slug, doc: null, error: true }))
    return () => {
      cancelled = true
    }
  }, [slug])

  const current = state.slug === slug
  return { doc: current ? state.doc : null, loading: !current, error: current && state.error }
}

export const formatDate = (iso) =>
  new Date(iso).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' })

export const formatPhone = (digits) =>
  digits?.length === 10 ? `(${digits.slice(0, 3)}) ${digits.slice(3, 6)}-${digits.slice(6)}` : digits

export const readingTime = (html) => Math.max(1, Math.round(html.replace(/<[^>]+>/g, ' ').split(/\s+/).length / 220))
